import { useRef } from "react";
import type { ButtonRenderer as ButtonData, HorizontalListRenderer, ShelfRenderer as ShelfData } from "../../../model/innertube.gen";
import type { Endpoint } from "../../../model/endpoints";
import type { FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { EndpointLink } from "../../../components/text/EndpointLink";
import { FormattedString } from "../../../components/text/FormattedString";
import { ButtonRenderer } from "../../../components/button/ButtonRenderer";
import { HorizontalList, type HorizontalListItem } from "./HorizontalList";
import styles from "./ShelfRenderer.module.css";

/** A horizontal list as a shelf's content. */
export function HorizontalListRendererView({ data }: { data: HorizontalListRenderer }) {
  return (
    <HorizontalList
      items={data.items as HorizontalListItem[]}
      data={data}
      previousButton={data.previousButton?.buttonRenderer as ButtonData | undefined}
      nextButton={data.nextButton?.buttonRenderer as ButtonData | undefined}
    />
  );
}

/**
 * A shelf of the channel's home tab: a title that links to the full list,
 * a play-all button, and a row of lockups.
 */
export function ShelfRenderer({ data }: { data: ShelfData }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const title = <FormattedString text={data.title as FormattedText} noLinks className={styles.title} />;
  const list = data.content.horizontalListRenderer;
  return (
    <div ref={ref} className={styles.shelf} data-renderer="shelfRenderer">
      <div className={styles.subheader}>
        <div className={styles.titleContainer}>
          <h2 className={styles.heading}>
            {data.endpoint ? (
              <EndpointLink endpoint={data.endpoint as Endpoint} className={styles.titleText}>
                {title}
              </EndpointLink>
            ) : (
              <span className={styles.titleText}>{title}</span>
            )}
            {data.playAllButton && (
              <div className={styles.playButton}>
                <ButtonRenderer data={data.playAllButton.buttonRenderer as ButtonData} />
              </div>
            )}
          </h2>
        </div>
      </div>
      {data.subtitle && <FormattedString text={data.subtitle as FormattedText} className={styles.subtitle} />}
      <div className={styles.contents}>{list && <HorizontalListRendererView data={list} />}</div>
    </div>
  );
}
