import { flags } from "../../../flags";

/** The gap between grid items, horizontally. */
export const ITEM_GAP = 16;

/**
 * The minimum item width for a grid of this width: the configured minimum,
 * smaller on narrower grids and larger on wider ones.
 */
function minItemWidth(width: number): number {
  const min = flags.number("rich_grid_min_item_width", 310);
  if (!flags.bool("rich_grid_enable_dynamic_offset", true)) return min;
  const anchor = flags.number("rich_grid_dynamic_offset_anchor_width", 1200);
  const per100 = flags.number("rich_grid_dynamic_offset_offset_per_100", 20);
  const lower = flags.number("rich_grid_dynamic_offset_lower_bound", -40);
  return min + Math.max(((width - anchor) / 100) * per100, lower);
}

export interface GridLayout {
  itemsPerRow: number;
  maxItemsPerRow: number;
  minItemWidth: number;
  maxItemWidth: number;
}

/** How many items fit in a row of a grid this wide, less the page gutters. */
export function gridLayout(width: number): GridLayout {
  const min = minItemWidth(width);
  const usable = width > 600 ? width - 48 : width;
  const max = flags.number("rich_grid_default_max_items_per_row", 6);
  return {
    itemsPerRow: Math.max(1, Math.min(Math.floor((usable + ITEM_GAP) / (min + ITEM_GAP)) || 1, max)),
    maxItemsPerRow: max,
    minItemWidth: min,
    maxItemWidth: flags.number("rich_grid_max_item_width", 500),
  };
}
