import { useInfiniteQuery } from "@tanstack/react-query";
import { useDeferredValue, useRef, useState, type CSSProperties } from "react";
import type { LockupViewModel as LockupData, RichGridRenderer, RichItemRenderer } from "../../../model/innertube.gen";
import { layoutRows, type PlacedItem } from "../../../model/channel";
import { Renderer } from "../../../renderers/Renderer";
import { useListStepEvents } from "../../../workload/stepEvents";
import { useImpression } from "../../../logging/impressions";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { LockupViewModel } from "../../../components/lockup/LockupViewModel";
import { ContinuationItem } from "../../../components/continuation/ContinuationItem";
import { gridQueryOptions } from "../queries";
import { gridLayout, ITEM_GAP } from "./gridLayout";
import styles from "./RichGrid.module.css";

/** The vertical space between rows. */
const ROW_GAP = 36;

/** The width of the guide beside a grid that is as wide as the page. */
function guideWidth(): number {
  const style = getComputedStyle(document.documentElement);
  return parseInt(style.getPropertyValue("--yt-guide-width"), 10) || parseInt(style.getPropertyValue("--yt-mini-guide-width"), 10) || 0;
}

function RichItem({ data, firstColumn }: { data: RichItemRenderer; firstColumn: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.item} data-renderer="richItemRenderer" data-first-column={firstColumn || undefined}>
      <div className={styles.content}>
        <LockupViewModel data={data.content.lockupViewModel as LockupData} orientation="vertical" className={styles.lockup} />
      </div>
    </div>
  );
}

function itemKey({ item }: PlacedItem): string {
  return (item.content.lockupViewModel as { contentId?: string }).contentId ?? item.trackingParams;
}

export interface RichGridProps {
  data: RichGridRenderer;
  query: ReturnType<typeof gridQueryOptions>;
}

/**
 * The video grid of a channel tab. The grid measures its width to choose
 * the items per row. A new grid renders its first row at once and the rest
 * in the background; more items load when the end comes into view.
 */
export function RichGrid({ data, query }: RichGridProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const grid = useInfiniteQuery(query);
  const pages = grid.data.pages;
  const continuation = pages.at(-1)?.continuation ?? null;
  // Null until the background render after the grid mounts.
  const shownPages = useDeferredValue(pages, null);

  const [layout, setLayout] = useState(() => gridLayout(0));
  const measure = () => {
    const el = ref.current;
    if (!el) return;
    const next = gridLayout(el.clientWidth - (el.offsetWidth === document.body.clientWidth ? guideWidth() : 0));
    setLayout((l) => (l.itemsPerRow === next.itemsPerRow && l.minItemWidth === next.minItemWidth ? l : next));
  };
  useResizeObserver(ref, measure);

  const placedPages = shownPages ?? pages;
  const placed = layoutRows(
    placedPages.flatMap((page) => page.items),
    layout.itemsPerRow,
    placedPages.at(-1)?.continuation != null,
  );
  // The first commit shows what a row can hold at most, before the grid
  // has measured how many items its rows hold.
  const shown = shownPages ? placed : placed.slice(0, layout.maxItemsPerRow);

  useListStepEvents(grid.data, data.targetId);

  const loadMore = () => {
    if (grid.hasNextPage && !grid.isFetchingNextPage) void grid.fetchNextPage();
  };
  const style = {
    "--yt-rich-grid-items-per-row": layout.itemsPerRow,
    "--yt-rich-grid-item-margin": `${ITEM_GAP}px`,
    "--yt-rich-grid-row-margin": `${ROW_GAP}px`,
    "--yt-rich-grid-item-max-width": `${layout.maxItemWidth}px`,
    "--yt-rich-grid-item-min-width": `${layout.minItemWidth}px`,
  } as CSSProperties;
  return (
    <div ref={ref} className={styles.grid} style={style} data-renderer="richGridRenderer">
      {data.header && (
        <div className={styles.header}>
          <Renderer data={data.header} />
        </div>
      )}
      <div className={styles.contents}>
        {shown.map((p) => (
          <RichItem key={itemKey(p)} data={p.item} firstColumn={p.column === 0} />
        ))}
        {continuation && <ContinuationItem key={pages.length} data={continuation} onVisible={loadMore} className={styles.continuation} />}
      </div>
    </div>
  );
}
