import type { ChannelPage } from "../../model/channel";
import { gridQueryOptions, type BrowseTarget } from "./queries";
import { TabbedPageHeader } from "./header/TabbedPageHeader";
import { HomeSections } from "./home/HomeSections";
import { RichGrid } from "./videos/RichGrid";
import styles from "./ChannelBrowse.module.css";

export interface ChannelBrowseProps {
  page: ChannelPage | undefined;
  /** The channel and tab that the page shows, for the grid's query. */
  target: BrowseTarget;
  focusSelectedTab: boolean;
}

/** The channel page layout: the header with the tabs, and the selected tab's content. */
export function ChannelBrowse({ page, target, focusSelectedTab }: ChannelBrowseProps) {
  return (
    <div className={styles.browse} data-page="channel">
      <div className={styles.header}>{page?.header && <TabbedPageHeader data={page.header} tabs={page.tabs} focusSelectedTab={focusSelectedTab} />}</div>
      <div className={styles.results}>
        <div className={styles.primary}>
          {page?.grid && page.gridFirst ? (
            <RichGrid data={page.grid} query={gridQueryOptions(target, page.grid.targetId, page.gridFirst)} />
          ) : (
            page && <HomeSections sections={page.sections} />
          )}
        </div>
      </div>
    </div>
  );
}
