import { useDeferredValue } from "react";
import type { ItemSectionRenderer } from "../../../model/innertube.gen";
import { ItemSection } from "../../../components/section/ItemSection";
import styles from "./HomeSections.module.css";

/** Sections rendered in the first commit of the home tab; the rest follow in the background. */
const FIRST_BATCH = 2;

/** The home tab: the featured video and the shelves, one item section each. */
export function HomeSections({ sections }: { sections: ItemSectionRenderer[] }) {
  const shown = useDeferredValue(sections, sections.slice(0, FIRST_BATCH));
  return (
    <div className={styles.list} data-renderer="sectionListRenderer">
      <div className={styles.contents}>
        {shown.map((section, i) => (
          <ItemSection key={`${section.trackingParams}:${i}`} data={section} className={styles.section} />
        ))}
      </div>
    </div>
  );
}
