import clsx from "clsx";
import { useLayoutEffect, useRef, useState } from "react";
import type { ButtonRenderer as ButtonData, LockupViewModel as LockupData, ShortsLockupViewModel } from "../../../model/innertube.gen";
import { rendererKey } from "../../../renderers/registry";
import { Renderer } from "../../../renderers/Renderer";
import { useImpression } from "../../../logging/impressions";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { LockupViewModel } from "../../../components/lockup/LockupViewModel";
import { ShortsLockup } from "../../../components/lockup/ShortsLockup";
import { ButtonRenderer } from "../../../components/button/ButtonRenderer";
import styles from "./HorizontalList.module.css";

/** Items rendered before the user pages through the list. */
const INITIAL_COUNT = 6;
/** How close to an end the list counts as being at it. */
const ARROW_THRESHOLD = 20;

export interface HorizontalListItem {
  lockupViewModel?: LockupData;
  shortsLockupViewModel?: ShortsLockupViewModel;
}

export interface HorizontalListProps {
  items: HorizontalListItem[];
  /** The list's own logging data, if it has any. */
  data?: { trackingParams?: string };
  previousButton: ButtonData | undefined;
  nextButton: ButtonData | undefined;
}

function ListItem({ item }: { item: HorizontalListItem }) {
  if (item.lockupViewModel) return <LockupViewModel data={item.lockupViewModel} orientation="vertical" wrapperClassName={styles.lockup} />;
  if (item.shortsLockupViewModel) return <ShortsLockup data={item.shortsLockupViewModel} className={styles.shorts} />;
  return <Renderer data={item} />;
}

/** The width an item takes in the row, with its margins. */
function itemWidth(item: Element): number {
  const style = getComputedStyle(item);
  return (item as HTMLElement).offsetWidth + (parseFloat(style.marginLeft) || 0) + (parseFloat(style.marginRight) || 0);
}

/** Whether the row, moved by `offset`, shows its last item. */
function isAtEnd(container: HTMLElement, row: HTMLElement, offset: number, canShowMore: boolean): boolean {
  if (!row.firstElementChild) return false;
  return !canShowMore && offset + container.clientWidth >= row.scrollWidth - ARROW_THRESHOLD;
}

/**
 * A row of lockups that pages sideways with arrow buttons. It renders its
 * first items, and the rest when the user pages forward.
 */
export function HorizontalList({ items, data, previousButton, nextButton }: HorizontalListProps) {
  const ref = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const itemsRef = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const [shownCount, setShownCount] = useState(INITIAL_COUNT);
  const [offset, setOffset] = useState(0);
  const [atEnd, setAtEnd] = useState(false);
  const canShowMore = items.length > shownCount;
  const shown = items.slice(0, shownCount);

  const updateButtons = () => {
    const container = containerRef.current;
    const row = itemsRef.current;
    if (container && row) setAtEnd(isAtEnd(container, row, offset, canShowMore));
  };
  useResizeObserver(containerRef, updateButtons);
  // Paging moves the row and renders more items, without resizing the container.
  useLayoutEffect(() => {
    const container = containerRef.current;
    const row = itemsRef.current;
    if (container && row) setAtEnd(isAtEnd(container, row, offset, canShowMore));
  }, [offset, canShowMore, shownCount]);

  const page = (direction: 1 | -1) => {
    const container = containerRef.current;
    const row = itemsRef.current;
    const first = row?.firstElementChild;
    if (!container || !row || !first) return;
    const width = itemWidth(first);
    const step = Math.round(container.clientWidth / width) * width;
    if (direction > 0) {
      setShownCount(items.length);
      setOffset(Math.min(offset + step, Math.max(0, width * items.length - container.clientWidth)));
    } else {
      setOffset(Math.max(0, offset - step));
    }
  };

  return (
    <div ref={ref} className={styles.list} data-renderer="horizontalListRenderer">
      {offset > ARROW_THRESHOLD && previousButton && (
        <div className={clsx(styles.arrow, styles.left)}>
          <ButtonRenderer data={previousButton} onClick={() => page(-1)} />
        </div>
      )}
      <div className={styles.scrollOuter}>
        <div ref={containerRef} className={styles.scrollContainer}>
          <div ref={itemsRef} className={styles.items} style={offset ? { transform: `translateX(${-offset}px)` } : undefined}>
            {shown.map((item, i) => (
              <ListItem key={rendererKey(item, i)} item={item} />
            ))}
          </div>
        </div>
      </div>
      {!atEnd && nextButton && (
        <div className={clsx(styles.arrow, styles.right)}>
          <ButtonRenderer data={nextButton} onClick={() => page(1)} />
        </div>
      )}
    </div>
  );
}
