import { useEffect, useEffectEvent, useRef } from "react";
import type { PageHeaderRenderer } from "../../../model/innertube.gen";
import type { ChannelTab } from "../../../model/channel";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { ImageBanner } from "./HeaderParts";
import { PageHeaderViewModel } from "./PageHeaderViewModel";
import { ChannelTabs } from "./ChannelTabs";
import styles from "./TabbedPageHeader.module.css";

/** How much slower than the page the banner moves while the header scrolls away. */
const PARALLAX_SCALAR = 0.5;

export interface TabbedPageHeaderProps {
  data: PageHeaderRenderer;
  tabs: ChannelTab[];
  /** Moves focus to the selected tab, after a tab change on the same channel. */
  focusSelectedTab: boolean;
}

/**
 * The channel header: the banner, the page header and the tab bar. While
 * the header scrolls away, the banner moves at half the scroll speed.
 */
export function TabbedPageHeader({ data, tabs, focusSelectedTab }: TabbedPageHeaderProps) {
  const headerRef = useRef<HTMLDivElement>(null);
  const toolbarRef = useRef<HTMLDivElement>(null);
  // The scroll distance over which the header condenses to its tab bar.
  const condenseHeight = useRef(0);
  const progress = useRef(-1);
  const vm = data.content.pageHeaderViewModel;
  const banner = vm.banner?.imageBannerViewModel;

  const applyScroll = () => {
    const height = condenseHeight.current;
    const p = height ? Math.min(1, Math.max(0, window.scrollY / height)) : 0;
    if (p === progress.current) return;
    progress.current = p;
    headerRef.current?.style.setProperty("--yt-banner-parallax-offset", `${Math.round(p * height * PARALLAX_SCALAR)}px`);
  };
  const measure = () => {
    const header = headerRef.current;
    const toolbar = toolbarRef.current;
    if (!header || !toolbar) return;
    condenseHeight.current = Math.max(0, header.offsetHeight - toolbar.offsetHeight);
  };
  useResizeObserver(headerRef, measure);
  const onScroll = useEffectEvent(applyScroll);
  useEffect(() => {
    const listener = () => onScroll();
    listener();
    window.addEventListener("scroll", listener, { passive: true });
    return () => window.removeEventListener("scroll", listener);
  }, []);

  return (
    <div className={styles.header} data-renderer="pageHeaderRenderer">
      <div ref={headerRef} className={styles.appHeader}>
        <div className={styles.pageHeaderContainer}>
          {banner && (
            <div className={styles.banner}>
              <div className={styles.bannerSizer}>
                <ImageBanner data={banner} />
              </div>
            </div>
          )}
          <div className={styles.pageHeader}>
            <PageHeaderViewModel data={vm} />
          </div>
        </div>
        {tabs.length > 1 && (
          <div ref={toolbarRef} className={styles.toolbar}>
            <div className={styles.tabsContainer}>
              <div className={styles.tabsInner}>
                <div className={styles.divider} />
                <ChannelTabs tabs={tabs} focusSelected={focusSelectedTab} />
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
