import clsx from "clsx";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { ChannelTab } from "../../../model/channel";
import type { Endpoint } from "../../../model/endpoints";
import { EndpointLink } from "../../../components/text/EndpointLink";
import { Icon } from "../../../components/icon/Icon";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import styles from "./ChannelTabs.module.css";

const messages = defineMessages({
  tabs: { id: "channel.tabs", defaultMessage: "Channel" },
  scrollLeft: { id: "channel.tabs.left", defaultMessage: "Scroll tabs left" },
  scrollRight: { id: "channel.tabs.right", defaultMessage: "Scroll tabs right" },
});

/** The gap between tabs, which the slider's offset includes. */
const TAB_GAP = 24;

interface TabShape {
  key: string;
  title: string;
  selected: boolean;
  endpoint: Endpoint | undefined;
  trackingParams: string | undefined;
}

function tabShapes(tabs: ChannelTab[]): TabShape[] {
  const out: TabShape[] = [];
  for (const tab of tabs) {
    const renderer = tab.tabRenderer ?? tab.expandableTabRenderer;
    if (!renderer) continue;
    out.push({
      key: renderer.endpoint.commandMetadata.webCommandMetadata.url,
      title: renderer.title,
      selected: !!renderer.selected,
      endpoint: renderer.endpoint as Endpoint,
      trackingParams: tab.tabRenderer?.trackingParams,
    });
  }
  return out;
}

interface Slider {
  width: number;
  offset: number;
}

/**
 * The tab group: one link per tab, each to the tab's own page, and the
 * underline below the selected tab, which is measured from the rendered
 * tabs and slides when the selection changes.
 */
function TabGroup({ tabs, focusSelected, label }: { tabs: ChannelTab[]; focusSelected: boolean; label: string }) {
  const shapes = tabShapes(tabs);
  const tabRefs = useRef<Array<HTMLAnchorElement | null>>([]);
  const [slider, setSlider] = useState<Slider>({ width: 48, offset: 0 });
  const [animated, setAnimated] = useState(false);
  const selected = shapes.findIndex((s) => s.selected);
  useLayoutEffect(() => {
    const target = tabRefs.current[selected];
    if (!target) return;
    let offset = 0;
    for (let i = 0; i < selected; i++) offset += Math.round(tabRefs.current[i]?.getBoundingClientRect().width ?? 0) + TAB_GAP;
    const width = Math.round(target.getBoundingClientRect().width);
    setSlider((s) => (s.width === width && s.offset === offset ? s : { width, offset }));
    if (focusSelected) target.focus({ preventScroll: true });
  }, [tabs, selected, focusSelected]);
  // The underline slides only once it has its first position.
  useEffect(() => {
    const frame = requestAnimationFrame(() => setAnimated(true));
    return () => cancelAnimationFrame(frame);
  }, []);
  return (
    <div className={styles.group}>
      <nav className={styles.tabs} aria-label={label}>
        {shapes.map((shape, i) => (
          <EndpointLink
            key={shape.key}
            ref={(el: HTMLAnchorElement | null) => {
              tabRefs.current[i] = el;
            }}
            endpoint={shape.endpoint}
            aria-current={shape.selected ? "page" : undefined}
            className={styles.tab}
          >
            <div className={clsx(styles.tabLabel, shape.selected && styles.tabLabelSelected)}>{shape.title}</div>
            <div className={styles.tabBar} />
          </EndpointLink>
        ))}
      </nav>
      <div className={clsx(styles.slider, animated && styles.sliderAnimated)} style={{ width: slider.width, transform: `translateX(${slider.offset}px)` }} />
    </div>
  );
}

interface Overflow {
  left: boolean;
  right: boolean;
}

/** The channel's tabs, scrollable with arrow buttons when they don't fit. */
export function ChannelTabs({ tabs, focusSelected }: { tabs: ChannelTab[]; focusSelected: boolean }) {
  const intl = useIntl();
  const containerRef = useRef<HTMLDivElement>(null);
  const [overflow, setOverflow] = useState<Overflow>({ left: false, right: false });
  const updateArrows = () => {
    const container = containerRef.current;
    if (!container) return;
    const left = container.scrollLeft > 0;
    const right = container.scrollLeft + container.clientWidth < container.scrollWidth;
    setOverflow((o) => (o.left === left && o.right === right ? o : { left, right }));
  };
  useResizeObserver(containerRef, updateArrows);
  const scrollBy = (direction: number) => {
    const container = containerRef.current;
    container?.scrollBy({ left: direction * container.clientWidth * 0.8, behavior: "smooth" });
  };
  return (
    <div className={styles.paperTabs}>
      {overflow.left && (
        <button type="button" className={styles.arrow} aria-label={intl.formatMessage(messages.scrollLeft)} onClick={() => scrollBy(-1)}>
          <Icon icon="CHEVRON_LEFT" />
        </button>
      )}
      <div ref={containerRef} className={styles.tabsContainer} onScroll={updateArrows}>
        <div className={styles.tabsContent}>
          <TabGroup tabs={tabs} focusSelected={focusSelected} label={intl.formatMessage(messages.tabs)} />
        </div>
      </div>
      {overflow.right && (
        <button type="button" className={styles.arrow} aria-label={intl.formatMessage(messages.scrollRight)} onClick={() => scrollBy(1)}>
          <Icon icon="CHEVRON_RIGHT" />
        </button>
      )}
    </div>
  );
}
