import { infiniteQueryOptions, queryOptions } from "@tanstack/react-query";
import { browse, continuation, player } from "../../api/innertube";
import { continuationParam, measured, type PageParam } from "../../api/requests";
import { parseResponse } from "../../model/response";
import type { ChannelHomeResponse, ChannelPlayerResponse, GridAppendResponse } from "../../model/innertube.gen";
import { channelPageFromResponse, gridPageFromAppend, type GridPage } from "../../model/channel";
import { endpointUrl, type Endpoint } from "../../model/endpoints";

const BROWSE_API = "/youtubei/v1/browse";

export interface BrowseTarget {
  browseId: string;
  params?: string;
  clickTrackingParams?: string;
}

/** A channel page: one browse request per channel and tab. */
export function channelQueryOptions({ browseId, params, clickTrackingParams }: BrowseTarget) {
  // The click tracking params only report which link led here.
  // eslint-disable-next-line @tanstack/query/exhaustive-deps
  return queryOptions({
    queryKey: ["browse", browseId, params ?? null],
    // Without a page to show, the route's error element replaces it.
    throwOnError: (_error, query) => query.state.data === undefined,
    queryFn: () =>
      measured("browse", "navigation", async () => channelPageFromResponse(parseResponse<ChannelHomeResponse>(await browse(browseId, params, clickTrackingParams)))),
  });
}

/**
 * The player response of a channel's featured video, which the channel
 * page requests on its own, after the browse response.
 */
export function channelPlayerQueryOptions(endpoint: Endpoint) {
  const videoId = endpoint.watchEndpoint?.videoId ?? "";
  // The endpoint adds only the page URL and click tracking to the request.
  // eslint-disable-next-line @tanstack/query/exhaustive-deps
  return queryOptions({
    queryKey: ["player", videoId],
    queryFn: async () => {
      const text = await player({ videoId, currentUrl: endpointUrl(endpoint), clickTrackingParams: endpoint.clickTrackingParams });
      return parseResponse<ChannelPlayerResponse>(text).response;
    },
  });
}

/**
 * The rich grid of a channel tab: the first page comes with the browse
 * response, later pages are continuations. Only continuations are
 * fetched, so the query never goes stale on its own.
 */
export function gridQueryOptions({ browseId, params }: BrowseTarget, targetId: string | undefined, first: GridPage) {
  // The first page and the target id come from the browse response,
  // which the browse id and params identify.
  // eslint-disable-next-line @tanstack/query/exhaustive-deps
  return infiniteQueryOptions({
    queryKey: ["grid", "browse", browseId, params ?? null],
    initialPageParam: null as PageParam | null,
    initialData: { pages: [first], pageParams: [null] },
    staleTime: Infinity,
    queryFn: async ({ pageParam }): Promise<GridPage> => {
      if (!pageParam) return first;
      return measured("browse", "continuation", async () =>
        gridPageFromAppend(parseResponse<GridAppendResponse>(await continuation("grid-append", BROWSE_API, pageParam.token, pageParam.clickTrackingParams)), targetId),
      );
    },
    getNextPageParam: (last) => continuationParam(last.continuation),
  });
}
