import clsx from "clsx";
import { useRef } from "react";
import type {
  AttributionViewModel,
  ButtonViewModel as ButtonData,
  DescriptionPreviewViewModel,
  DynamicTextViewModel,
  FlexibleActionsViewModel,
  ImageBannerViewModel,
} from "../../../model/innertube.gen";
import type { Endpoint } from "../../../model/endpoints";
import type { AttributedText } from "../../../model/text";
import { useImpression, logClick } from "../../../logging/impressions";
import { useRunCommand } from "../../../commands/useRunCommand";
import { AttributedString } from "../../../components/text/AttributedString";
import { TruncatedText } from "../../../components/text/TruncatedText";
import { ButtonViewModel } from "../../../components/button/ButtonViewModel";
import { Image } from "../../../components/image/Image";
import styles from "./HeaderParts.module.css";

/** The page title, clamped to its maximum number of lines. */
export function DynamicText({ data, large }: { data: DynamicTextViewModel; large: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={clsx(styles.title, large ? styles.titleLarge : styles.titleMedium)}>
      <h1 className={styles.titleText} aria-label={data.rendererContext.accessibilityContext?.label} style={{ WebkitLineClamp: data.maxLines || 2 }}>
        <AttributedString text={data.text as AttributedText} inheritLinkColor />
      </h1>
    </div>
  );
}

/** The start of the channel description; a click opens the full description. */
export function DescriptionPreview({ data, maxLines }: { data: DescriptionPreviewViewModel; maxLines: number | undefined }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const context = data.rendererContext;
  const command = context.commandContext?.onTap?.innertubeCommand as Endpoint | undefined;
  const open = () => {
    logClick(data);
    runCommand(command);
  };
  return (
    <div ref={ref} className={clsx(styles.description, command && styles.clickable)} onClick={command ? open : undefined}>
      <TruncatedText
        text={data.description as AttributedText}
        truncationText={data.truncationText as AttributedText}
        maxLines={maxLines ?? data.maxLines}
        label={context.accessibilityContext?.label}
        onExpand={open}
      />
    </div>
  );
}

/** The attribution line: the channel's links. */
export function Attribution({ data }: { data: AttributionViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.attribution}>
      <span className={styles.attributionText}>
        <AttributedString text={data.text as AttributedText} inheritLinkColor className={styles.noWrap} />
      </span>
      {data.suffix && (
        <span className={styles.attributionSuffix}>
          <AttributedString text={data.suffix as AttributedText} />
        </span>
      )}
    </div>
  );
}

/** The header's action buttons, in rows. */
export function FlexibleActions({ data, stacked }: { data: FlexibleActionsViewModel; stacked: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const actions = data.actionsRows.flatMap((row) => row.actions);
  return (
    <div
      ref={ref}
      className={clsx(styles.actions, !stacked && styles.actionsInline)}
      style={data.minimumRowHeight ? { minHeight: data.minimumRowHeight } : undefined}
    >
      {actions.map((action, i) => (
        <div key={i} className={styles.action}>
          <ButtonViewModel data={action.buttonViewModel as ButtonData} />
        </div>
      ))}
    </div>
  );
}

/** The channel banner above the header. */
export function ImageBanner({ data }: { data: ImageBannerViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={clsx(styles.banner, data.style === "IMAGE_BANNER_STYLE_INSET" && styles.bannerInset)}>
      <Image image={data.image.sources} width={1060} />
    </div>
  );
}
