import { useLayoutEffect, useRef, useState } from "react";
import type { AttributedText } from "../../model/text";
import { AttributedString } from "./AttributedString";
import styles from "./TruncatedText.module.css";

export interface TruncatedTextProps {
  text: AttributedText | undefined;
  /** The text of the button that expands the text, such as "...more". */
  truncationText: AttributedText | undefined;
  maxLines: number | undefined;
  label?: string;
  onExpand?: () => void;
}

/**
 * Text clamped to `maxLines`, with a button at the end of the last line
 * when the text doesn't fit. An unclamped hidden copy measures the text.
 */
export function TruncatedText({ text, truncationText, maxLines, label, onExpand }: TruncatedTextProps) {
  const visibleRef = useRef<HTMLDivElement>(null);
  const hiddenRef = useRef<HTMLDivElement>(null);
  const [overflowing, setOverflowing] = useState(false);
  useLayoutEffect(() => {
    const visible = visibleRef.current;
    const hidden = hiddenRef.current;
    if (visible && hidden) setOverflowing(hidden.scrollHeight > visible.clientHeight + 1);
  }, [text, maxLines]);
  return (
    <div className={styles.host}>
      <div ref={visibleRef} className={styles.content} style={maxLines ? { WebkitLineClamp: maxLines } : undefined}>
        <AttributedString text={text} />
      </div>
      <div ref={hiddenRef} className={styles.hiddenContent} aria-hidden="true">
        <AttributedString text={text} />
      </div>
      {overflowing && (
        <button
          type="button"
          className={styles.button}
          aria-label={label}
          onClick={(e) => {
            e.stopPropagation();
            onExpand?.();
          }}
        >
          <AttributedString text={truncationText} />
        </button>
      )}
    </div>
  );
}
