import { useRef } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { ButtonRenderer as ButtonData, MenuRenderer, ReelShelfRenderer } from "../../../model/innertube.gen";
import type { FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { FormattedString } from "../../../components/text/FormattedString";
import { Icon } from "../../../components/icon/Icon";
import { Menu } from "../../../components/menu/Menu";
import { HorizontalList, type HorizontalListItem } from "./HorizontalList";
import styles from "./ReelShelf.module.css";

const messages = defineMessages({
  previous: { id: "reelShelf.previous", defaultMessage: "Previous" },
  next: { id: "reelShelf.next", defaultMessage: "Next" },
});

/** An arrow button for a list whose response has none. */
function arrowButton(icon: string, label: string): ButtonData {
  return { icon: { iconType: icon }, accessibility: { label }, style: "STYLE_DEFAULT", size: "SIZE_DEFAULT" } as ButtonData;
}

/** The Shorts shelf: a header with the Shorts icon and a row of Shorts lockups. */
export function ReelShelf({ data }: { data: ReelShelfRenderer }) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const menu = data.button?.menuRenderer as MenuRenderer | undefined;
  return (
    <div ref={ref} className={styles.shelf} data-renderer="reelShelfRenderer">
      <div className={styles.header}>
        {data.icon && (
          <div className={styles.imageContainer}>
            <Icon icon={data.icon.iconType} />
          </div>
        )}
        <div className={styles.titleContainer}>
          <h2 className={styles.heading}>
            <FormattedString text={data.title as FormattedText} className={styles.title} />
          </h2>
        </div>
        {menu && (
          <div className={styles.menu}>
            <Menu data={menu} />
          </div>
        )}
      </div>
      <HorizontalList
        items={data.items as HorizontalListItem[]}
        previousButton={arrowButton("CHEVRON_LEFT", intl.formatMessage(messages.previous))}
        nextButton={arrowButton("CHEVRON_RIGHT", intl.formatMessage(messages.next))}
      />
    </div>
  );
}
