import { useQuery } from "@tanstack/react-query";
import { useState } from "react";
import { useLocation } from "react-router";
import { parseChannelPath, type ChannelPath, type Endpoint } from "../../model/endpoints";
import { useNavigateFinishEvent } from "../../workload/stepEvents";
import { useNavigationFinished, useNavigationTelemetry } from "../../hooks/useNavigationTelemetry";
import { usePageTitle } from "../../hooks/usePageTitle";
import { channelQueryOptions, type BrowseTarget } from "./queries";
import { ChannelBrowse } from "./ChannelBrowse";
import "./renderers";

interface Shown {
  pathname: string;
  path: ChannelPath;
  endpoint: Endpoint | undefined;
  /** Whether the previous page shown here was a tab of the same channel. */
  sameChannel: boolean;
}

/**
 * What to browse for a channel URL: the browse endpoint that led here, or
 * else the channel from the URL.
 */
function browseTarget({ path, endpoint }: Shown): BrowseTarget {
  const browse = endpoint?.browseEndpoint;
  return {
    browseId: browse?.browseId ?? path.channel,
    params: browse?.params,
    clickTrackingParams: endpoint?.clickTrackingParams,
  };
}

/**
 * The channel page, one instance per channel tab. While another page is
 * shown, this one stays mounted but hidden (PageStack) and keeps its tab.
 */
export default function ChannelPage() {
  const location = useLocation();
  const path = parseChannelPath(location.pathname);
  const endpoint = (location.state as { endpoint?: Endpoint } | null)?.endpoint;
  const [shown, setShown] = useState<Shown | null>(path ? { pathname: location.pathname, path, endpoint, sameChannel: false } : null);
  if (path && location.pathname !== shown?.pathname) {
    setShown({ pathname: location.pathname, path, endpoint, sameChannel: shown?.path.channel === path.channel });
  }
  if (!shown) return null;
  return <Channel key={shown.pathname} target={browseTarget(shown)} focusSelectedTab={shown.sameChannel} />;
}

function Channel({ target, focusSelectedTab }: { target: BrowseTarget; focusSelectedTab: boolean }) {
  useNavigationTelemetry("browse", "browse");
  const channel = useQuery(channelQueryOptions(target));
  const page = channel.data;
  useNavigationFinished(page !== undefined);
  usePageTitle(page?.title);
  useNavigateFinishEvent(page);
  return <ChannelBrowse page={page} target={target} focusSelectedTab={focusSelectedTab} />;
}
