import type {
  ChannelHomeResponse,
  ContinuationItemRenderer,
  ExpandableTabRenderer,
  GridAppendResponse,
  ItemSectionRenderer,
  PageHeaderRenderer,
  RichGridRenderer,
  RichItemRenderer,
  TabRenderer,
} from "./innertube.gen";
import type { Processed } from "./response";

// The channel page model. A browse response carries the page header, the
// tabs and the content of the selected tab: the home tab's sections (the
// featured video and the shelves) or the rich grid of the Videos tab.
// Grid continuations append rich items.

export type ChannelTab = { tabRenderer?: TabRenderer; expandableTabRenderer?: ExpandableTabRenderer };

/** An entry of a rich grid: an item, or the continuation at its end. */
export type GridEntry = { richItemRenderer?: RichItemRenderer; continuationItemRenderer?: ContinuationItemRenderer };

export interface GridPage {
  items: RichItemRenderer[];
  continuation: ContinuationItemRenderer | null;
}

export interface ChannelPage {
  title: string;
  header: PageHeaderRenderer | null;
  tabs: ChannelTab[];
  /** The home tab's item sections, empty on other tabs. */
  sections: ItemSectionRenderer[];
  grid: RichGridRenderer | null;
  /** The first page of the grid, which the grid's infinite query starts from. */
  gridFirst: GridPage | null;
}

function splitGrid(entries: GridEntry[]): GridPage {
  const items: RichItemRenderer[] = [];
  let continuation: ContinuationItemRenderer | null = null;
  for (const entry of entries) {
    if (entry.richItemRenderer) items.push(entry.richItemRenderer);
    else if (entry.continuationItemRenderer) continuation = entry.continuationItemRenderer;
  }
  return { items, continuation };
}

/** The content of the selected tab: the first selected tab that has content. */
function selectedContent(tabs: ChannelTab[]): TabRenderer["content"] | null {
  for (const tab of tabs) {
    const renderer = tab.tabRenderer;
    if (renderer?.selected && renderer.content) return renderer.content;
  }
  return null;
}

/** Turns a browse response (home or Videos tab) into the page model. */
export function channelPageFromResponse({ response }: Processed<ChannelHomeResponse>): ChannelPage {
  const tabs = (response.contents?.twoColumnBrowseResultsRenderer?.tabs ?? []) as ChannelTab[];
  const content = selectedContent(tabs);
  const sections = (content?.sectionListRenderer?.contents ?? []).flatMap((c) => (c.itemSectionRenderer ? [c.itemSectionRenderer] : []));
  const grid = content?.richGridRenderer ?? null;
  const title = response.microformat?.microformatDataRenderer?.title?.trim() || response.metadata?.channelMetadataRenderer?.title?.trim() || "";
  return {
    title,
    header: response.header?.pageHeaderRenderer ?? null,
    tabs,
    sections,
    grid,
    gridFirst: grid ? splitGrid(grid.contents as GridEntry[]) : null,
  };
}

/** The rich items that a grid continuation appends to the grid with this target id. */
export function gridPageFromAppend({ commands }: Processed<GridAppendResponse>, targetId: string | undefined): GridPage {
  const entries: GridEntry[] = [];
  for (const c of commands) {
    const append = c.appendContinuationItemsAction as { targetId?: string; continuationItems?: GridEntry[] } | undefined;
    if (append && (!targetId || append.targetId === targetId)) entries.push(...(append.continuationItems ?? []));
  }
  return splitGrid(entries);
}

/** A grid item with its place in the layout. */
export interface PlacedItem {
  item: RichItemRenderer;
  row: number;
  column: number;
}

/**
 * Lays the items out in rows of `perRow`. While more items can load, the
 * incomplete last row waits for them, so that rows don't change after they
 * are shown.
 */
export function layoutRows(items: RichItemRenderer[], perRow: number, hasMore: boolean): PlacedItem[] {
  const count = hasMore ? items.length - (items.length % perRow) : items.length;
  return items.slice(0, count).map((item, i) => ({ item, row: Math.floor(i / perRow), column: i % perRow }));
}
