import { useRef } from "react";
import type { ContentMetadataViewModel as ContentMetadataData, PageHeaderViewModel as PageHeaderData } from "../../../model/innertube.gen";
import { useImpression } from "../../../logging/impressions";
import { useMediaQuery } from "../../../hooks/useMediaQuery";
import { DecoratedAvatar } from "../../../components/lockup/LockupMetadata";
import { ContentMetadata } from "../../../components/lockup/ContentMetadata";
import { Attribution, DescriptionPreview, DynamicText, FlexibleActions } from "./HeaderParts";
import styles from "./PageHeaderViewModel.module.css";

/**
 * The header's responsive level: 1 below 528 px, 2 below 840 px, 3 below
 * 1024 px, else 4.
 */
function useResponsiveLevel(): number {
  const narrow = useMediaQuery("(max-width: 527.9px)");
  const medium = useMediaQuery("(max-width: 839.9px)");
  const wide = useMediaQuery("(max-width: 1023.9px)");
  if (narrow) return 1;
  if (medium) return 2;
  if (wide) return 3;
  return 4;
}

/** The avatar size for the level and the number of filled header fields. */
function avatarSize(level: number, fields: number): string {
  if (level === 1) return "AVATAR_SIZE_XL";
  if (level === 2 || (level === 4 && fields < 4)) return "AVATAR_SIZE_XXL";
  return "AVATAR_SIZE_XXXL";
}

function filledFields(data: PageHeaderData): number {
  return [data.title, data.metadata, data.actions, data.description, data.attribution].filter(Boolean).length;
}

/**
 * The channel's page header: avatar, name, metadata, description preview,
 * links and actions. Wide windows show everything beside the avatar;
 * narrow ones move the description and actions below it.
 */
export function PageHeaderViewModel({ data }: { data: PageHeaderData }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const level = useResponsiveLevel();
  const wide = level >= 3;
  const avatar = data.image?.decoratedAvatarViewModel;
  const title = data.title?.dynamicTextViewModel;
  const metadata = data.metadata?.contentMetadataViewModel as ContentMetadataData | undefined;
  const description = data.description?.descriptionPreviewViewModel;
  const attribution = data.attribution?.attributionViewModel;
  const actions = data.actions?.flexibleActionsViewModel;
  const trailing = (
    <>
      {attribution && <Attribution data={attribution} />}
      {actions && <FlexibleActions data={actions} stacked={level <= 2} />}
    </>
  );
  return (
    <div ref={ref} className={styles.host} data-renderer="pageHeaderViewModel">
      <div className={styles.content}>
        <div className={styles.headline}>
          {avatar && (
            <div className={styles.headlineImage}>
              <DecoratedAvatar data={avatar} size={avatarSize(level, filledFields(data))} />
            </div>
          )}
          <div className={styles.headlineInfo}>
            {title && <DynamicText data={title} large={wide} />}
            {metadata && <ContentMetadata data={metadata} inline={level > 1} className={styles.metadata} />}
            {wide && description && <DescriptionPreview data={description} maxLines={1} />}
            {wide && trailing}
          </div>
        </div>
        {!wide && (
          <div className={styles.headlineInfo}>
            {description && <DescriptionPreview data={description} maxLines={undefined} />}
            {trailing}
          </div>
        )}
      </div>
    </div>
  );
}
