import { useQuery } from "@tanstack/react-query";
import { useLayoutEffect, useRef, useState } from "react";
import { defineMessages, useIntl } from "react-intl";
import type { ChannelVideoPlayerRenderer } from "../../../model/innertube.gen";
import type { Endpoint } from "../../../model/endpoints";
import type { FormattedText } from "../../../model/text";
import { useImpression } from "../../../logging/impressions";
import { useResizeObserver } from "../../../hooks/useResizeObserver";
import { FormattedString } from "../../../components/text/FormattedString";
import { RetryMessage } from "../../../components/feedback/RetryMessage";
import { VideoMetaBlock, type VideoMetaBlockProps } from "../../../components/lockup/VideoMetaBlock";
import { Player, type PlayerData } from "../../player/Player";
import { channelPlayerQueryOptions } from "../queries";
import styles from "./ChannelVideoPlayer.module.css";

const messages = defineMessages({
  error: { id: "channel.player.error", defaultMessage: "The video could not be loaded." },
});

/** The player before its response arrives: the chrome without a video. */
const NO_VIDEO: PlayerData = {};

interface Size {
  width: number;
  height: number;
}

/**
 * The description beside the featured video, cut to its box, with the
 * "read more" link when it doesn't fit.
 */
function DescriptionExpander({ text, readMore }: { text: FormattedText; readMore: FormattedText }) {
  const contentRef = useRef<HTMLDivElement>(null);
  const [overflowing, setOverflowing] = useState(false);
  useLayoutEffect(() => {
    const content = contentRef.current;
    if (content) setOverflowing(content.scrollHeight > content.clientHeight);
  }, [text]);
  return (
    <div className={styles.description}>
      <div ref={contentRef} className={styles.descriptionContent}>
        <FormattedString text={text} className={styles.descriptionText} />
      </div>
      {overflowing && <FormattedString text={readMore} className={styles.more} />}
    </div>
  );
}

/**
 * The channel's featured video: an inline player, which requests its own
 * player response, beside the video's title, views and description.
 */
export function ChannelVideoPlayer({ data }: { data: ChannelVideoPlayerRenderer }) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const playerResponse = useQuery(channelPlayerQueryOptions(data.inlinePlaybackEndpoint as unknown as Endpoint));
  const containerRef = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState<Size>({ width: 0, height: 0 });
  const measure = () => {
    const container = containerRef.current;
    if (!container) return;
    const width = container.clientWidth;
    const height = container.clientHeight;
    setSize((s) => (s.width === width && s.height === height ? s : { width, height }));
  };
  useResizeObserver(containerRef, measure);
  return (
    <div ref={ref} className={styles.host} data-renderer="channelVideoPlayerRenderer">
      <div ref={containerRef} className={styles.playerContainer}>
        {playerResponse.isError ? (
          <RetryMessage text={intl.formatMessage(messages.error)} onRetry={() => void playerResponse.refetch()} className={styles.playerError} />
        ) : (
          <Player response={playerResponse.data ?? NO_VIDEO} width={size.width} height={size.height} playerId="c4-player" />
        )}
      </div>
      <div className={styles.content}>
        <div className={styles.metadataContainer}>
          <FormattedString text={data.title as FormattedText} className={styles.title} as="h3" />
          <VideoMetaBlock data={{ viewCountText: data.viewCountText, publishedTimeText: data.publishedTimeText } as VideoMetaBlockProps["data"]} />
        </div>
        <DescriptionExpander text={data.description as FormattedText} readMore={data.readMoreText as FormattedText} />
      </div>
    </div>
  );
}
